// Applied rules: [C3, III④]
// Skipped rules: [III④: Abstain on hits [5, 6, 7, 8]: these are mask-produced/non-monotone ring-buffer indices (`cur_ix_masked`, `prev_ix`, `+1` probes) inside a hot loop, so slice/index rewrite would not form a forward iterator and would likely add persistent bounds checks; C3 hoisting is the correct standalone fix.; C3.S1: Signature lift to references/slices is unnecessary here and would require caller proof across the call graph; the profitable invariant loads can be handled with S2 local hoists entirely within the function.]
#[inline(always)]
unsafe fn FindAllMatchesH10(
    mut self_0: *mut H10,
    mut dictionary: *const BrotliEncoderDictionary,
    mut data: *const uint8_t,
    ring_buffer_mask: size_t,
    cur_ix: size_t,
    max_length: size_t,
    max_backward: size_t,
    dictionary_distance: size_t,
    mut params: *const BrotliEncoderParams,
    mut matches: *mut BackwardMatch,
) -> size_t {
    let orig_matches: *mut BackwardMatch = matches;
    let mut match_count: size_t = 0 as size_t;
    let cur_ix_masked: size_t = cur_ix & ring_buffer_mask;
    let mut best_len: size_t = 1 as size_t;
    let short_match_max_backward: size_t = (if (*params).quality != HQ_ZOPFLIFICATION_QUALITY {
        16 as c_int
    } else {
        64 as c_int
    }) as size_t;
    let mut stop: size_t = cur_ix.wrapping_sub(short_match_max_backward);
    let mut dict_matches: [uint32_t; 38] = [0; 38];
    let mut i: size_t = 0;
    if cur_ix < short_match_max_backward {
        stop = 0 as size_t;
    }
    let cur_byte0: uint8_t = *data.offset(cur_ix_masked as isize);
    let cur_byte1: uint8_t = *data.offset(cur_ix_masked.wrapping_add(1 as size_t) as isize);
    i = cur_ix.wrapping_sub(1 as size_t);
    while i > stop && best_len <= 2 as size_t {
        let mut prev_ix: size_t = i;
        let backward: size_t = cur_ix.wrapping_sub(prev_ix);
        if (backward > max_backward) as c_int as c_long != 0 {
            break;
        }
        prev_ix = (prev_ix as c_ulong & ring_buffer_mask as c_ulong) as size_t;
        if !(cur_byte0 as c_int != *data.offset(prev_ix as isize) as c_int
            || cur_byte1 as c_int
                != *data.offset(prev_ix.wrapping_add(1 as size_t) as isize) as c_int)
        {
            let len: size_t = FindMatchLengthWithLimit(
                data.offset(prev_ix as isize) as *const uint8_t,
                data.offset(cur_ix_masked as isize) as *const uint8_t,
                max_length,
            ) as size_t;
            if len > best_len {
                best_len = len;
                InitBackwardMatch(matches.offset(match_count as isize), backward, len);
                match_count = match_count.wrapping_add(1);
            }
        }
        i = i.wrapping_sub(1);
    }
    matches = matches.offset(match_count as isize);
    if best_len < max_length {
        matches = StoreAndFindMatchesH10(
            self_0,
            data,
            cur_ix,
            ring_buffer_mask,
            max_length,
            max_backward,
            &raw mut best_len,
            matches,
        );
    }
    i = 0 as size_t;
    while i <= BROTLI_MAX_STATIC_DICTIONARY_MATCH_LEN as size_t {
        dict_matches[i as usize] = kInvalidMatch;
        i = i.wrapping_add(1);
    }
    let mut minlen: size_t = brotli_max_size_t(4 as size_t, best_len.wrapping_add(1 as size_t));
    let max_distance: size_t = (*params).dist.max_distance;
    if BrotliFindAllStaticDictionaryMatches(
        dictionary,
        data.offset(cur_ix_masked as isize) as *const uint8_t,
        minlen,
        max_length,
        (&raw mut dict_matches as *mut uint32_t).offset(0 as c_int as isize) as *mut uint32_t,
    ) != 0
    {
        let mut maxlen: size_t = brotli_min_size_t(37 as size_t, max_length);
        let mut l: size_t = 0;
        let dict_distance_base: size_t = dictionary_distance.wrapping_add(1 as size_t);
        let dict_matches_base: *mut BackwardMatch = matches;
        let mut dict_match_count: size_t = 0 as size_t;
        l = minlen;
        while l <= maxlen {
            let mut dict_id: uint32_t = dict_matches[l as usize];
            if dict_id < kInvalidMatch {
                let mut distance: size_t =
                    dict_distance_base.wrapping_add((dict_id >> 5 as c_int) as size_t);
                if distance <= max_distance {
                    InitDictionaryBackwardMatch(
                        dict_matches_base.offset(dict_match_count as isize),
                        distance,
                        l,
                        (dict_id & 31 as uint32_t) as size_t,
                    );
                    dict_match_count = dict_match_count.wrapping_add(1);
                }
            }
            l = l.wrapping_add(1);
        }
        matches = dict_matches_base.offset(dict_match_count as isize);
    }
    return matches.offset_from(orig_matches) as c_long as size_t;
}

